typeDefinitions.declaration:
export interface RadioOption {
  value: string;
  label: ReactNode;
  description?: ReactNode;
  disabled?: boolean;
  minInlineSize?: number;
}

export interface RadioGroupProps extends Omit<HTMLAttributes<HTMLFieldSetElement>, "onChange"> {
  /** The question. Rendered as the group's legend. */
  legend: ReactNode;
  /** Shared form name. Required: two groups sharing one name are one group. */
  name: string;
  options: RadioOption[];
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  disabled?: boolean;
}

example.usage:
import { RadioGroup, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example() {
  const options = [{ value: "review", label: "Review" }, { value: "release", label: "Release" }];
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <RadioGroup legend="Access" name="access" options={options}/>
    </div>
  </>;
}
